// Private experimental transport. Exact bytes, no archives, networking or persistence.
import {canonical,digest,verifyReceipt} from './core.js';
import {importReport} from './file-problem.js';
import {importCorrection} from './correction-sidecar.js';
import {appendContributionWal,verifyContributionWal,safeViewingProjection} from './contribution-wal.js';
export const BUNDLE_SCHEMA='reckoner.private-contribution-wal-bundle.experimental.v1';
export const BUNDLE_LIMITS=Object.freeze({fileBytes:8*1024*1024,decodedBytes:6*1024*1024,packetBytes:2*1024*1024,snapshotBytes:2*1024*1024,snapshots:100,priorWals:99});
const E=new TextEncoder(),D=new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}),need=(v,m)=>{if(!v)throw Error(m);},hash=v=>typeof v==='string'&&/^[a-f0-9]{64}$/.test(v);
const exact=(v,k)=>need(v&&typeof v==='object'&&!Array.isArray(v)&&Object.keys(v).sort().join('|')===[...k].sort().join('|'),'Unexpected bundle keys');
const decimal=v=>need(typeof v==='string'&&/^[1-9][0-9]*$/.test(v)&&Number.isSafeInteger(Number(v)),'Invalid byte count');
function b64(bytes){let s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(s);}
function un64(s,max){need(typeof s==='string'&&s.length<=Math.ceil(max/3)*4&&/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(s),'Invalid or oversized base64');const a=atob(s),b=Uint8Array.from(a,x=>x.charCodeAt(0));need(b64(b)===s,'Noncanonical base64');return b;}
async function packed(b){return {sha256:await digest(b),bytes:String(b.length),base64:b64(b)};}
async function unpack(v,max){exact(v,['sha256','bytes','base64']);decimal(v.bytes);need(hash(v.sha256)&&Number(v.bytes)<=max,'Invalid packed hash or size');const b=un64(v.base64,max);need(b.length===Number(v.bytes)&&await digest(b)===v.sha256,'Packed hash or size mismatch');return b;}
function subset(rows,snapshots){const ids=new Set(rows.flatMap(r=>JSON.parse(r.artifact_manifest).map(m=>m.sha256)));return new Map([...snapshots].filter(([h])=>ids.has(h)));}
function pins(expected){const g=expected.expectedGenesis??null,t=expected.expectedTip??null;need((g===null&&t===null)||(hash(g)&&hash(t)),'Enter both independent genesis and tip, or leave both blank');return {expectedGenesis:g,expectedTip:t};}
export async function encodePrivateWalBundle({bytes,snapshots,priorWals=[]},expected={}){const checkpoint=pins(expected);need(bytes instanceof Uint8Array&&bytes.length<=2*1024*1024&&snapshots instanceof Map&&snapshots.size<=BUNDLE_LIMITS.snapshots,'Bundle input budget');need(Array.isArray(priorWals)&&priorWals.length<=BUNDLE_LIMITS.priorWals,'Prior WAL budget');let ownedTotal=bytes.length;for(const b of [...snapshots.values(),...priorWals]){need(b instanceof Uint8Array&&b.length>0&&b.length<=BUNDLE_LIMITS.snapshotBytes,'Bundle input byte budget');ownedTotal+=b.length;need(ownedTotal<=BUNDLE_LIMITS.decodedBytes,'Decoded aggregate budget');}bytes=new Uint8Array(bytes);snapshots=new Map([...snapshots].map(([h,b])=>[h,new Uint8Array(b)]));priorWals=priorWals.map(b=>new Uint8Array(b));const verification=await verifyContributionWal(bytes,snapshots,checkpoint);need(verification.rows.every(r=>JSON.parse(r.release_scope).audience==='private_local_review'),'Private-only workbench rejects public-export rows');need(priorWals.length===verification.rows.length-1,'Every exact prior WAL must be retained');let total=bytes.length;need(snapshots.size<=BUNDLE_LIMITS.snapshots,'Snapshot count budget');for(const b of snapshots.values()){need(b.length<=BUNDLE_LIMITS.snapshotBytes,'Snapshot size budget');total+=b.length;}for(let i=0;i<priorWals.length;i++){const b=priorWals[i];need(b instanceof Uint8Array&&b.length<bytes.length,'Prior WAL shape');total+=b.length;need(total<=BUNDLE_LIMITS.decodedBytes,'Decoded aggregate budget');need(b.every((v,j)=>v===bytes[j]),'Prior WAL is not exact current prefix');const past=await verifyContributionWal(b,subset(verification.rows.slice(0,i+1),snapshots));need(past.rows.length===i+1&&past.tip===verification.rows[i].row_digest,'Prior WAL history mismatch');}need(total<=BUNDLE_LIMITS.decodedBytes,'Decoded aggregate budget');const bundle={schema:BUNDLE_SCHEMA,wal:await packed(bytes),snapshots:await Promise.all([...snapshots].sort(([a],[b])=>a.localeCompare(b)).map(async([,b])=>packed(b))),priorWals:await Promise.all(priorWals.map(packed))};const raw=E.encode(canonical(bundle));need(raw.length<=BUNDLE_LIMITS.fileBytes,'Bundle byte budget');return {bundleBytes:raw,verification,bytes:new Uint8Array(bytes),snapshots:new Map([...snapshots].map(([h,b])=>[h,new Uint8Array(b)])),priorWals:priorWals.map(b=>new Uint8Array(b))};}
export async function reopenPrivateWalBundle(input,expected={}){need(input instanceof Uint8Array&&input.length>0&&input.length<=BUNDLE_LIMITS.fileBytes,'Bundle file budget');const raw=D.decode(input),v=JSON.parse(raw);exact(v,['schema','wal','snapshots','priorWals']);need(v.schema===BUNDLE_SCHEMA&&canonical(v)===raw,'Unsupported or noncanonical bundle');need(Array.isArray(v.snapshots)&&v.snapshots.length>0&&v.snapshots.length<=BUNDLE_LIMITS.snapshots&&Array.isArray(v.priorWals)&&v.priorWals.length<=BUNDLE_LIMITS.priorWals,'Bundle count budget');let announced=0;for(const x of [v.wal,...v.snapshots,...v.priorWals]){decimal(x.bytes);announced+=Number(x.bytes);need(announced<=BUNDLE_LIMITS.decodedBytes,'Decoded aggregate budget');}const bytes=await unpack(v.wal,2*1024*1024),snapshots=new Map();for(const x of v.snapshots){need(!snapshots.has(x.sha256),'Duplicate bundle snapshot');snapshots.set(x.sha256,await unpack(x,BUNDLE_LIMITS.snapshotBytes));}const priorWals=[];for(const x of v.priorWals)priorWals.push(await unpack(x,2*1024*1024));const checked=await encodePrivateWalBundle({bytes,snapshots,priorWals},expected);need(checked.bundleBytes.length===input.length&&checked.bundleBytes.every((b,i)=>b===input[i]),'Noncanonical snapshot ordering');return checked;}
export async function inspectPacket(input){need(input instanceof Uint8Array&&input.length>0&&input.length<=BUNDLE_LIMITS.packetBytes,'Packet size budget');const bytes=new Uint8Array(input),raw=D.decode(bytes),v=JSON.parse(raw);let schema,body,contributor,assistance,reviewers=[],eventAt='UNKNOWN';if(v.schema==='garrison.cairn.receipt.v0.1'){await verifyReceipt(v);schema=v.schema;body=v;const active=v.revisions.find(r=>r.id===v.activeRevisionId)||v.revisions.at(-1);contributor=active?.reading?.contributor||'UNKNOWN';assistance=active?.reading?.assistance?.trim()?'AI-assisted':'UNKNOWN';eventAt=active?.observedAt||'UNKNOWN';reviewers=v.reviews.map(r=>({label:r.reviewer,role:r.role??'reviewer',eventId:r.id}));}else if(v.report?.schema==='file.problem-report.v1'){await importReport(raw);schema=v.report.schema;body=v.report;contributor=body.contributor;assistance=body.assistance;}else if(v.proposal?.schema==='ocr.correction-sidecar.v1'){await importCorrection(raw);schema=v.proposal.schema;body=v.proposal;contributor=body.attribution.contributor;assistance=body.attribution.assistance;}else throw Error('Unsupported full JSON packet schema');return {bytes,sha256:await digest(bytes),schema,contributor,assistance,reviewers,eventAt:schema==='garrison.cairn.receipt.v0.1'?eventAt:body.createdAt??'UNKNOWN'};}
export async function preparePrivateWalSave({packetBytes,creator,recordId,eventId,purpose,method,savedAt,localOnly=false,previous=null,expected={},priorKept=false}){need(localOnly===true,'Confirm local-only inspection and download; no sharing');for(const [k,v]of Object.entries({creator,recordId,eventId,purpose,method}))need(typeof v==='string'&&v.trim().length>0&&E.encode(v).length<=1000,'Missing or oversized '+k);const packet=await inspectPacket(packetBytes),p=pins(expected);if(previous){need(priorKept===true,'Keep/download the prior archive before appending');need(hash(p.expectedGenesis)&&hash(p.expectedTip),'Both independent checkpoints are required to append');need(recordId===previous.verification.rows[0].record_id,'Reopened record ID must stay fixed');}
 const h=packet.sha256,manifest=[{role:'primary',mediaType:'application/json',schema:packet.schema,sha256:h,bytes:String(packet.bytes.length),objectName:h+'.json',evidenceCompleteness:'source_bytes_not_carried'}];const fields={record_id:recordId,event_id:eventId,event_at:packet.eventAt,saved_at:savedAt,source_ref:'[]',source_time:'[]',actor_attribution:canonical({sourceActors:['UNKNOWN'],publisher:'UNKNOWN',contributor:packet.contributor,creator}),reviewer_attribution:canonical(packet.reviewers.map(r=>({...r,artifactSha256:h}))),assistance_attribution:canonical({declaration:packet.assistance,provider:'UNKNOWN',model:'UNKNOWN',runtime:'UNKNOWN',persona:'UNKNOWN',methodVersion:'private-workbench.experimental.v1'}),purpose,method,uncertainty:'not_assessed',artifact_manifest:canonical(manifest),target_selector:canonical([{artifactSha256:h,pointer:''}])};const snapshots=new Map(previous?.snapshots??[]);snapshots.set(h,packet.bytes);const saved=await appendContributionWal({previousBytes:previous?.bytes??null,snapshots,fields,...p});return encodePrivateWalBundle({...saved,priorWals:previous?[...previous.priorWals,previous.bytes]:[]});}
export async function privateWalView(prepared){return safeViewingProjection(prepared.bytes,prepared.snapshots);}
